});

test('createInvoice reports UNKNOWN_SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate arguments', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 10 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 10 }]);
  result.value.lines[0].qty = 999;
  assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 10 }]);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

